def lower_bound(values, target):
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

assert lower_bound([1, 2, 2, 4], 2) == 1
assert lower_bound([], 2) == 0

def stair_ways(n):
    if n < 0:
        raise ValueError("n must be nonnegative")
    ways = [0] * (n + 1)
    ways[0] = 1
    for step in range(1, n + 1):
        ways[step] = ways[step - 1]
        if step >= 2:
            ways[step] += ways[step - 2]
    return ways[n]

assert stair_ways(0) == 1
assert stair_ways(4) == 5
